VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,7.39,"Lecture one. Reliable, scalable and maintainable systems. This is what keeps a data system working."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":16.672,"caps":[[0.5,5.15,"One big server does all the work."],[5.4,9.01,"Too many requests get dropped."],[9.26,12.87,"One crash, and everything is down."],[13.12,16.09,"Even a repair means downtime."]],"warp":[[0,0],[0.5,0.5],[5.4,4],[9.26,5.8],[13.12,8.8],[16.672,10.8]]},{"dur":25.008,"caps":[[0.5,3.79,"Against crashes, keep a copy in each city."],[4.04,6.69,"Now the link is cut."],[6.94,13.51,"London sells a ticket; New York never hears."],[13.76,19.45,"Stay consistent: refuse to answer."],[19.7,23.79,"Stay available: answer, maybe stale."]],"warp":[[0,0],[0.5,0.6],[4.04,3.3],[6.94,4.7],[13.76,7.4],[19.7,9.9],[25.008,12.2]]},{"dur":23.429,"caps":[[0.99,5.96,"A database stores data for tomorrow."],[6.21,9.82,"A cache keeps answers close."],[10.07,13.92,"A hit takes 2 ms, a miss 100 ms."],[14.17,17.78,"An index: 20 checks, not a million."],[18.03,21.48,"A batch job crunches it overnight."]],"warp":[[0,0],[0.99,1.8],[6.21,3.9],[10.07,6.75],[14.17,9],[18.03,12],[23.429,14.2]]},{"dur":25.124,"caps":[[0.5,5.15,"10,000 disks: about one dies every day."],[5.4,10.05,"A dead disk is a fault."],[10.3,15.19,"One copy: a dead disk is a failure."],[15.44,20.25,"Two copies: users notice nothing."],[20.5,24.11,"Faults must not become failures."]],"warp":[[0,0],[0.5,0.5],[5.4,3],[10.3,4.7],[15.44,7.95],[20.5,10],[25.124,12.1]]},{"dur":33.111,"caps":[[0.5,6.99,"Six servers share the load, 70 each."],[7.24,12.69,"One dies; five carry on at 84 each."],[12.94,17.75,"One more dies: 105 each, over 100."],[18,23.53,"Overload makes them fall one by one."],[23.78,27.31,"The last one carries all 420."],[27.56,32.13,"One bug hits all six together."]],"warp":[[0,0],[0.5,0.4],[7.24,2.75],[12.94,5.05],[18,7.05],[23.78,9.3],[27.56,11.8],[33.111,13.7]]},{"dur":33.344,"caps":[[0.5,5.55,"100 requests, each timed."],[5.8,10.53,"Most are quick; a few are slow."],[10.78,15.19,"The average is 250 ms."],[15.44,20.41,"p95: 95 in 100 are faster."],[20.66,25.95,"p99: 99 in 100 are faster."],[26.2,31.25,"The average hides the slowest."]],"warp":[[0,0],[0.5,0.7],[5.8,3],[10.78,4.9],[15.44,6.7],[20.66,8.7],[26.2,10.3],[33.344,12.3]]},{"dur":45.093,"caps":[[0.55,4.56,"Approach 1: one write per post."],[4.81,8.82,"Reading means 3 lookups and a merge."],[9.07,14.36,"Approach 2: copy to each follower."],[14.61,19.5,"Reading is one lookup."],[19.75,24.24,"Reads outnumber posts 65 to 1."],[24.49,34.18,"So fan out: 345,000 writes a second."],[34.43,40.44,"A celebrity post takes 87 s, not 5."],[40.69,44.14,"Hybrid: celebrities merge on read."]],"warp":[[0,0],[0.55,1],[4.81,2.8],[9.07,5.4],[14.61,7.45],[19.75,9.55],[24.49,11.45],[34.43,14.65],[40.69,16.85],[45.093,19.75]]},{"dur":25.124,"caps":[[0.5,4.59,"Need 8 times the capacity of one machine."],[4.84,12.29,"One big machine costs about 4 times more."],[12.54,18.23,"One dies: nothing left, or 88% left."],[18.48,23.77,"Only scale out reaches 40x, but must coordinate."]],"warp":[[0,0],[0.5,0.8],[4.84,3.3],[12.54,6.2],[18.48,9],[25.124,11.9]]},{"dur":25.194,"caps":[[0.5,6.59,"Easy to run, understand and change."],[6.84,12.85,"Every service uses every database."],[13.1,17.59,"Swap a database: edit all five."],[17.84,21.05,"A layer in between: 9 connections."],[21.3,23.71,"Now only the layer changes."]],"warp":[[0,0],[0.5,0.75],[6.84,3.95],[13.1,6.3],[17.84,8.35],[21.3,10.5],[25.194,12.5]]},{"dur":13.328,"caps":[],"warp":[[0,0],[0.5,0.9],[4.68,2],[8.06,3.1],[13.328,9]]}]};
